import{_ as e,a as o,b as r,c as a}from"./chunks/fs62-1.Bm5-9Q4-.js";import{_ as n,a as l,b as i,c as s}from"./chunks/fs55-1.Dvhuqj4q.js";import{_ as g,o as p,c as d,a4 as u}from"./chunks/framework.B0hSrcZ6.js";const c="/cases-img/fs59-0.png",h="/cases-img/fs59-1.jpg",m="/cases-img/fs60-0.jpg",k="/cases-img/fs60-1.jpg",f="/cases-img/fs58-0.jpg",b="/cases-img/fs58-1.jpg",y="/cases-img/fs53-0.jpg",x="/cases-img/fs53-1.png",B="/cases-img/fs54-0.jpg",_="/cases-img/fs54-1.jpg",w="/cases-img/fs57-0.jpg",G="/cases-img/fs57-1.jpg",E=JSON.parse('{"title":"英文长文精选（下）","description":"本页精选海外实战下篇，聚焦 Grok Bot 全天候运行与多角色协同。详解工程运维、岗位切分与成本控制，指导读者建立任务状态机，避免上下文胀破与额度浪费。","frontmatter":{},"headers":[],"relativePath":"cases/en2.md","filePath":"cases/en2.md","lastUpdated":1792210948000}'),q={name:"cases/en2.md"};function A(H,t,z,T,v,F){return p(),d("div",null,[...t[0]||(t[0]=[u(`<h1 id="英文长文精选-下" tabindex="-1">英文长文精选（下） <a class="header-anchor" href="#英文长文精选-下" aria-label="Permalink to &quot;英文长文精选（下）&quot;">​</a></h1><p>搞 7×24 小时后台自动化和多 Agent 协同，<strong>最怕角色边界模糊</strong>。把所有杂活和权限塞给单个 Bot，上下文很快胀破，容易在网页上误操作，一天就能耗光一周额度。</p><p>另一个坑是盲目新建 Bot。<strong>缺乏任务看板与交付状态机</strong>，最后只能整天在聊天框里手动捞信息。</p><p>这里精选了 2026 年 8 月到 10 月期间海外沉淀的 12 篇实战长文，核心机制都在下表里。</p><table tabindex="0"><thead><tr><th style="text-align:left;">主题分类</th><th style="text-align:left;">来源与篇目</th><th style="text-align:left;">核心业务场景</th><th style="text-align:left;">关键机制与工具</th></tr></thead><tbody><tr><td style="text-align:left;">自动化运维</td><td style="text-align:left;">Gipp：24/7 Repo Ops</td><td style="text-align:left;">仓库巡检与 CI 报错自动修复</td><td style="text-align:left;">6 具名 Bot 与 Kimi K3，设 Draft PR 防线</td></tr><tr><td style="text-align:left;">自动化运维</td><td style="text-align:left;">Morlex：Opus 5.5</td><td style="text-align:left;">强推理模型接入与复杂任务分解</td><td style="text-align:left;">Chief 调度中枢、Cursor Agent 与数据红线</td></tr><tr><td style="text-align:left;">自动化运维</td><td style="text-align:left;">社区：Issue 修复流水线</td><td style="text-align:left;">全天候 GitHub Issue 自动化修复</td><td style="text-align:left;">/workspace/devdesk 状态机、独立 Review 与熔断上报</td></tr><tr><td style="text-align:left;">团队架构</td><td style="text-align:left;">Movez：9 席位团队</td><td style="text-align:left;">官方 9 席位多 Agent 配置</td><td style="text-align:left;">5 信号切分、Attention List，缺数直接报错</td></tr><tr><td style="text-align:left;">团队架构</td><td style="text-align:left;">distort：数字员工</td><td style="text-align:left;">首个数字员工配置与晋升规范</td><td style="text-align:left;">五大岗位字段、纯文字推演与可逆性权限</td></tr><tr><td style="text-align:left;">团队架构</td><td style="text-align:left;">社区：6 Bot 编队</td><td style="text-align:left;">6 Bot 极简研运编队搭建</td><td style="text-align:left;">独立记忆切分、5 态看板与清晨 5 点站会</td></tr><tr><td style="text-align:left;">团队架构</td><td style="text-align:left;">社区：29 个 Agent</td><td style="text-align:left;">跨领域多 Agent 协同飞轮</td><td style="text-align:left;">调度入口 Emma、Cursor Agent 配合跨角色接力</td></tr><tr><td style="text-align:left;">一人公司</td><td style="text-align:left;">maestro：Top 10</td><td style="text-align:left;">覆盖销售、招聘与法务提示词</td><td style="text-align:left;">差异表与草稿交付、通用五行防线及专属凭证</td></tr><tr><td style="text-align:left;">一人公司</td><td style="text-align:left;">beamnxw：一人公司</td><td style="text-align:left;">一人数字企业业务运转支架</td><td style="text-align:left;">公司简报单源、六字段看板与 Auto Review</td></tr><tr><td style="text-align:left;">记忆控费</td><td style="text-align:left;">n2parko：Team Bots</td><td style="text-align:left;">组织级知识资产化与共享同事</td><td style="text-align:left;">Databot、10x Engineer 与隔离双层记忆</td></tr><tr><td style="text-align:left;">记忆控费</td><td style="text-align:left;">Radar：控费组合拳</td><td style="text-align:left;">额度快速耗尽归因与控费</td><td style="text-align:left;">唤醒频率控制、Duplicate 斩断上下文与脚本批处理</td></tr><tr><td style="text-align:left;">记忆控费</td><td style="text-align:left;">rari：记忆工程规范</td><td style="text-align:left;">共享 Team Bot 记忆工程规范</td><td style="text-align:left;">五类上下文容器、快慢时钟与外部审查卡片</td></tr></tbody></table><p>准备搭建多 Bot 协同流程时，<strong>把提示词直接发给主 Bot</strong>，梳理岗位边界与执行目录。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我打算参考英文社区的工程与自动化实践，在 Grok Bot 中搭建一套多 Agent 工作流：【填入具体业务场景，例如夜间代码缺陷巡检 / 一人公司日常运营】。</span></span>
<span class="line"><span>请帮我完成以下设计：</span></span>
<span class="line"><span>1. 明确角色编制：列出所需 Bot 清单（包括唯一的调度入口 Chief 与各专职角色），按「记忆边界」与「审批范围」划清每个角色的职责。</span></span>
<span class="line"><span>2. 规划工作目录：在云电脑 /workspace 下设计标准文件夹层次，定义状态转移文件（如 status.json、task.md），规范上下游交付物的流转格式。</span></span>
<span class="line"><span>3. 设立权限人闸：区分完全可逆的自动执行动作与不可逆的报批动作，明确外部发信、代码合并、资金支付与修改生产配置的拦截规则。</span></span>
<span class="line"><span>4. 优化额度消耗：为定时例程规划低频运行策略与「无新内容保持静默」机制，标出哪些批量规则计算应交由终端 Python 脚本处理。</span></span></code></pre></div><h2 id="自动化研发与工程运维" tabindex="-1">自动化研发与工程运维 <a class="header-anchor" href="#自动化研发与工程运维" aria-label="Permalink to &quot;自动化研发与工程运维&quot;">​</a></h2><p>代码仓库的日常维护充满偶发测试报错、依赖补丁和规范检查。把机械性工作交给后台 Agent 处理能省下大量时间，核心在于严格限制改动范围与合并权限。</p><h3 id="how-to-build-a-24-7-repo-ops-desk-on-grok-bot-kimi-k3-complete-guide-gipp-🦅" tabindex="-1">How to Build a 24/7 Repo Ops Desk on Grok Bot + Kimi K3 (Complete Guide)｜Gipp 🦅 <a class="header-anchor" href="#how-to-build-a-24-7-repo-ops-desk-on-grok-bot-kimi-k3-complete-guide-gipp-🦅" aria-label="Permalink to &quot;How to Build a 24/7 Repo Ops Desk on Grok Bot + Kimi K3 (Complete Guide)｜Gipp 🦅&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/gippp69/status/2095088203690570191" target="_blank" rel="noreferrer">How to Build a 24/7 Repo Ops Desk on Grok Bot + Kimi K3 (Complete Guide)</a><br> 作者：<a href="https://x.com/gippp69" target="_blank" rel="noreferrer">Gipp 🦅 @gippp69</a></p></blockquote><p><img src="`+e+'" alt="How to Build a 24/7 Repo Ops Desk on Grok Bot + Kimi K3 (Complete Guide)" decoding="async"></p><p><img src="'+o+'" alt="How to Build a 24/7 Repo Ops Desk on Grok Bot + Kimi K3 (Complete Guide)" loading="lazy" decoding="async"></p><p>架构用 Grok Bot 当交互总控台，底层靠 Kimi K3 扛并发监控异常，单机号称能跑 300 个子 Agent，一共部署 6 个具名 Bot。</p><ol><li>Fix Bot 读取待修清单，专修 flaky test 和格式规范，自动提 Draft PR。</li><li><strong>脚本绝不碰业务逻辑</strong>，而且<strong>只提待审草稿，绝不自动合入主分支</strong>。</li><li><strong>先在边缘低风险仓库跑一周</strong>，看补丁采纳率再决定要不要扩充。</li></ol><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/Lw4rwhHVNi3gECk0KH5cRl0znJh" target="_blank" rel="noreferrer">阅读原文</a></p><h3 id="grok-bot-opus-5-5-the-ultimate-agent-harness-in-10-steps-morlex" tabindex="-1">Grok Bot + Opus 5.5: The Ultimate Agent Harness in 10 Steps｜Morlex <a class="header-anchor" href="#grok-bot-opus-5-5-the-ultimate-agent-harness-in-10-steps-morlex" aria-label="Permalink to &quot;Grok Bot + Opus 5.5: The Ultimate Agent Harness in 10 Steps｜Morlex&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/0xMorlex/status/2108171726412464173" target="_blank" rel="noreferrer">Grok Bot + Opus 5.5: The Ultimate Agent Harness in 10 Steps</a><br> 作者：<a href="https://x.com/0xMorlex" target="_blank" rel="noreferrer">Morlex @0xMorlex</a></p></blockquote><p><img src="'+c+'" alt="Grok Bot + Opus 5.5: The Ultimate Agent Harness in 10 Steps" loading="lazy" decoding="async"></p><p><img src="'+h+'" alt="Grok Bot + Opus 5.5: The Ultimate Agent Harness in 10 Steps" loading="lazy" decoding="async"></p><p>Grok Bot 引入 Claude Opus 5.5 后，Morlex 梳理了十步配置法，重点是<strong>以操作可逆性划分人闸</strong>。</p><ol><li>架构上由通用 Bot Chief 统筹，按业务派生专能 Bot，并调动 Cursor 云端 Agent 协同编码。</li><li>检索、排版与草稿由 Bot 自主执行；涉及外部发信与资金变动，<strong>一律停下报批</strong>。</li><li>设立明确红线，禁止 Bot 检索财务目录、法律文件与敏感密钥。</li></ol><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/A7BxwdM4QicxNZkmAWzcIt13nTh" target="_blank" rel="noreferrer">阅读原文</a></p><h3 id="grok-bot-opus-5-5-build-a-24-7-ai-engineering-team-in-12-steps" tabindex="-1">Grok Bot + Opus 5.5: Build a 24/7 AI Engineering Team in 12 Steps <a class="header-anchor" href="#grok-bot-opus-5-5-build-a-24-7-ai-engineering-team-in-12-steps" aria-label="Permalink to &quot;Grok Bot + Opus 5.5: Build a 24/7 AI Engineering Team in 12 Steps&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/0xjmori/status/2109648700897116554" target="_blank" rel="noreferrer">Grok Bot + Opus 5.5: Build a 24/7 AI Engineering Team in 12 Steps</a><br> 作者：<a href="https://x.com/0xjmori" target="_blank" rel="noreferrer">Mori @0xjmori</a></p></blockquote><p><img src="'+r+'" alt="Grok Bot + Opus 5.5: Build a 24/7 AI Engineering Team in 12 Steps" loading="lazy" decoding="async"></p><p><img src="'+a+'" alt="Grok Bot + Opus 5.5: Build a 24/7 AI Engineering Team in 12 Steps" loading="lazy" decoding="async"> Mori 在云电脑 <code>/workspace/devdesk</code> 跑状态机修 GitHub 缺陷，由 Chief 调度四个专职角色推进。</p><ol><li>Triage 复现故障并提供失败用例。</li><li>Builder 调 Cursor 云端 Agent 独立分支写补丁。</li><li>Reviewer 独立复核，交由 Release 发布。</li></ol><ul><li>验收：<strong>补丁交付必须包含复现用例的前后对比执行日志</strong>。</li><li>熔断：<strong>同一测试报错两次立即停机呼叫人工</strong>，防止死循环空耗额度。</li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/PxkpwzPFgi4NgCktD8NcfCpmnYf" target="_blank" rel="noreferrer">阅读原文</a></p><h2 id="团队架构与岗位拆解" tabindex="-1">团队架构与岗位拆解 <a class="header-anchor" href="#团队架构与岗位拆解" aria-label="Permalink to &quot;团队架构与岗位拆解&quot;">​</a></h2><p>多 Bot 协同的核心在于理清组织架构。很多团队建立多个 Bot 后效率反而下降，根源在于岗位边界重叠、缺乏统一调度入口以及把单次对话经验错当成长期制度。</p><h3 id="grokbot-agents-build-a-team-that-works-for-you-24-7-in-10-steps-full-course-movez" tabindex="-1">GrokBot Agents: build a team that works for you 24/7 in 10 steps (Full-Course)｜Movez <a class="header-anchor" href="#grokbot-agents-build-a-team-that-works-for-you-24-7-in-10-steps-full-course-movez" aria-label="Permalink to &quot;GrokBot Agents: build a team that works for you 24/7 in 10 steps (Full-Course)｜Movez&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/0xMovez/status/2100261918896169259" target="_blank" rel="noreferrer">GrokBot Agents: build a team that works for you 24/7 in 10 steps (Full-Course)</a><br> 作者：<a href="https://x.com/0xMovez" target="_blank" rel="noreferrer">Movez @0xMovez</a></p></blockquote><p><img src="'+n+'" alt="GrokBot Agents: build a team that works for you 24/7 in 10 steps (Full-Course)" loading="lazy" decoding="async"></p><p><img src="'+l+'" alt="GrokBot Agents: build a team that works for you 24/7 in 10 steps (Full-Course)" loading="lazy" decoding="async"></p><p>任务全堆给单 Bot 容易越做越乱。Movez 拆解了 SpaceXAI 的 <strong>9 席位 Agent 架构</strong>，给出从单次试验到常驻例程的七步路径。</p><ul><li><strong>5 个拆分信号</strong>：目标与工具分化，或风格、日程与审批边界不同时，拆建新 Bot。</li><li><strong>配专属幕僚长</strong>：只管日历与收件箱，按真实交互维护动态清单，平时保持静默。</li><li><strong>守好两条红线</strong>：数据缺失或过期直接报错，<strong>严禁自行编造</strong>；定好重试逻辑与失败边界前，<strong>坚决不开定时例程</strong>。</li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/LSfqwAew5i4h3mkuQT9cgw3jn54" target="_blank" rel="noreferrer">阅读原文</a></p><h3 id="grok-bot-how-to-hire-your-first-ai-employee-full-guide-distort" tabindex="-1">Grok Bot: How to Hire Your First AI Employee (Full Guide)｜distort <a class="header-anchor" href="#grok-bot-how-to-hire-your-first-ai-employee-full-guide-distort" aria-label="Permalink to &quot;Grok Bot: How to Hire Your First AI Employee (Full Guide)｜distort&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/distortgeekin/status/2105275395901726845" target="_blank" rel="noreferrer">Grok Bot: How to Hire Your First AI Employee (Full Guide)</a><br> 作者：<a href="https://x.com/distortgeekin" target="_blank" rel="noreferrer">distort @distortgeekin</a></p></blockquote><p><img src="'+i+'" alt="Grok Bot: How to Hire Your First AI Employee (Full Guide)" loading="lazy" decoding="async"></p><p><img src="'+s+'" alt="Grok Bot: How to Hire Your First AI Employee (Full Guide)" loading="lazy" decoding="async"></p><p>Profile 要包含 Owns、Inputs、May、Must ask before 和 Done when 五个字段。</p><p>带它上手分四步走。</p><ol><li>一句话定职责，先挑高频易撤销的杂事。</li><li>执行前先用纯文字推演步骤与疑虑。</li><li>走完旁观、改规则、放手三轮测试。</li><li><strong>按动作可逆性分权</strong>，调研草稿自主做，不可逆操作卡死人工审批。</li></ol><p>交付验收必须卡死底线，<strong>遇到不确定停下询问</strong>，绝不能暗中猜测。</p><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/KGhnwWY0QiQrhgkKy2FcgECtnnc" target="_blank" rel="noreferrer">阅读原文</a></p><h3 id="grok-bot-how-to-build-your-first-ai-team-full-guide" tabindex="-1">Grok Bot: How to Build Your First AI Team (Full Guide) <a class="header-anchor" href="#grok-bot-how-to-build-your-first-ai-team-full-guide" aria-label="Permalink to &quot;Grok Bot: How to Build Your First AI Team (Full Guide)&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/distortgeekin/status/2108897917729738810" target="_blank" rel="noreferrer">Grok Bot: How to Build Your First AI Team (Full Guide)</a><br> 作者：<a href="https://x.com/distortgeekin" target="_blank" rel="noreferrer">distort @distortgeekin</a></p></blockquote><p><img src="'+m+'" alt="Grok Bot: How to Build Your First AI Team (Full Guide)" loading="lazy" decoding="async"></p><p><img src="'+k+'" alt="Grok Bot: How to Build Your First AI Team (Full Guide)" loading="lazy" decoding="async"> distort 分享了用 6 个 Bot 驱动高并发业务的架构（自述单月合并超 2000 个 PR），适合搭建 3 到 6 人 Bot 体系参考：</p><ul><li><strong>Chief of Staff 负责统筹</strong>：作为唯一中枢对接口，<strong>严禁亲自写代码或做具体任务</strong>。</li><li><strong>专职 Bot 切分业务</strong>：各自保留独立记忆，任务全沉淀在线上看板推进。</li><li><strong>清晨 5 点自动站会</strong>：运营 Bot 遍历各角色同步规范，<strong>靠定期校准解决上下文漂移</strong>。</li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/MRhNwTEH8i0PrDkSp5uce2V7nKe" target="_blank" rel="noreferrer">阅读原文</a></p><h3 id="how-i-use-grok-bot-my-team-of-29-ai-agents" tabindex="-1">How I use Grok Bot: My team of 29 AI agents <a class="header-anchor" href="#how-i-use-grok-bot-my-team-of-29-ai-agents" aria-label="Permalink to &quot;How I use Grok Bot: My team of 29 AI agents&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/melvindvivas/status/2109480575421808962" target="_blank" rel="noreferrer">How I use Grok Bot: My team of 29 AI agents</a><br> 作者：<a href="https://x.com/melvindvivas" target="_blank" rel="noreferrer">Melvin Vivas @melvindvivas</a> Melvin Vivas（@melvindvivas）用总管 Emma 串联 <strong>29 个 Agent</strong>（自述未核），分调研、研发、内容与商务 4 组协作。</p></blockquote><ol><li>调研 Bot 发现新模型，Emma 派代码 Bot 调 Cursor 云端 Agent 写范例并提 GitHub PR。</li><li>内容团队接力出教程草稿，各 Bot 用<strong>共享云电脑文件系统</strong>互传物料。</li><li><strong>定期审计并下线无用任务</strong>，避免多 Bot 带来无效背景消耗。</li></ol><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/YBjswa1rnivPkjk5BpscN6mcnDh" target="_blank" rel="noreferrer">阅读原文</a></p><h2 id="一人公司与实战指令" tabindex="-1">一人公司与实战指令 <a class="header-anchor" href="#一人公司与实战指令" aria-label="Permalink to &quot;一人公司与实战指令&quot;">​</a></h2><h3 id="_10-套岗位提示词-maestro" tabindex="-1">10 套岗位提示词｜maestro <a class="header-anchor" href="#_10-套岗位提示词-maestro" aria-label="Permalink to &quot;10 套岗位提示词｜maestro&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/maestrooth/status/2105288063391875450" target="_blank" rel="noreferrer">Top 10 Grok Bot Prompts That Replace an Entire Team</a><br> 作者：<a href="https://x.com/maestrooth" target="_blank" rel="noreferrer">maestro @maestrooth</a></p></blockquote><p>这套现成指令覆盖销售拓展、简历初筛与合同审查等 10 个场景。Bot 只产出草稿、差异比对或整理清单，<strong>绝不跨过外部执行红线</strong>。</p><ul><li>风险隔离：多 Bot 共享同一云电脑环境，必须用专用邮箱与独立卡号。</li><li>验收标准：事实陈述必须附带原始网页链接，无证据直接丢弃。</li><li>防线机制：全局规则写入五行防线，每次执行完毕必须汇报处理条数、跳过项和具体报错。</li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/MKHywsPUNinwvEkIF9icQgj2nJg" target="_blank" rel="noreferrer">阅读原文</a></p><h3 id="单人公司业务支架-beamnxw" tabindex="-1">单人公司业务支架｜beamnxw ./ <a class="header-anchor" href="#单人公司业务支架-beamnxw" aria-label="Permalink to &quot;单人公司业务支架｜beamnxw ./&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/beamnxw/status/2107143806546002398" target="_blank" rel="noreferrer">Grok Bot Engineering: Set Up a Harness for Your One-Person Company</a><br> 作者：<a href="https://x.com/beamnxw" target="_blank" rel="noreferrer">beamnxw ./ @beamnxw</a></p></blockquote><p><img src="'+f+'" alt="Grok Bot Engineering: Set Up a Harness for Your One-Person Company" loading="lazy" decoding="async"></p><p><img src="'+b+'" alt="Grok Bot Engineering: Set Up a Harness for Your One-Person Company" loading="lazy" decoding="async"></p><p>这套支架以 Operator 为核心，用单源简报锁死报价、客群与审批底线，搭配六字段看板跟踪流转。</p><ul><li>减少重复：单源业务简报作为行为基准，避免每次派活重复交代背景。</li><li>人工把关：<strong>执行不可逆操作前主动挂起</strong>，关键决策留在人手里。</li><li>日常巡检：跑通的流程沉淀为标准 Skill，工作日早晨 9 点通过 Routine 自动巡检看板。</li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/NYakw8hzLiScECkQ1b5ctWBmnvm" target="_blank" rel="noreferrer">阅读原文</a></p><h2 id="记忆工程与成本控制" tabindex="-1">记忆工程与成本控制 <a class="header-anchor" href="#记忆工程与成本控制" aria-label="Permalink to &quot;记忆工程与成本控制&quot;">​</a></h2><p>Bot 接入团队协作和定时调度后，最容易踩的坑就是<strong>记忆被带偏和额度跑飞</strong>。建立分层记忆并配合克制调度，系统才能长期跑下去。</p><h3 id="meet-your-team-bots-n2parko" tabindex="-1">Meet your Team Bots｜n2parko <a class="header-anchor" href="#meet-your-team-bots-n2parko" aria-label="Permalink to &quot;Meet your Team Bots｜n2parko&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/n2parko/status/2104663299485020568" target="_blank" rel="noreferrer">Meet your Team Bots</a><br> 作者：<a href="https://x.com/n2parko" target="_blank" rel="noreferrer">n2parko @n2parko</a></p></blockquote><p><img src="'+y+'" alt="Meet your Team Bots" loading="lazy" decoding="async"></p><p><img src="'+x+'" alt="Meet your Team Bots" loading="lazy" decoding="async"> n2parko（@n2parko）介绍了官方 Team Bots 机制，适合想沉淀专有知识、减少高频咨询的主管。这套功能在 Web 与 Slack 运行，主打<strong>全局团队记忆加个人独立笔记的双层机制</strong>。</p><ul><li>专家建专属 Bot：SpaceXAI 数据团队打造的 Databot 熟悉数据湖与可视化（自述覆盖超 4.5 万张数据表，未核），替专家挡掉大量琐碎咨询；工程与市场也各设专属 Bot 统一步调。</li><li>沉淀经验：把业务专家的隐性经验固化为共享工具，同时保护个人交互私密性。</li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/KS9Cwan52idy1xkLbnTcSC3xnxb" target="_blank" rel="noreferrer">阅读原文</a></p><h3 id="how-to-stop-your-grok-bot-from-eating-a-week-of-usage-in-a-day-fan-grok-bot-radar" tabindex="-1">How to Stop Your Grok Bot From Eating a Week of Usage in a Day｜Fan Grok Bot Radar <a class="header-anchor" href="#how-to-stop-your-grok-bot-from-eating-a-week-of-usage-in-a-day-fan-grok-bot-radar" aria-label="Permalink to &quot;How to Stop Your Grok Bot From Eating a Week of Usage in a Day｜Fan Grok Bot Radar&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/GrokBotRadar/status/2105065358038360334" target="_blank" rel="noreferrer">How to Stop Your Grok Bot From Eating a Week of Usage in a Day</a><br> 作者：<a href="https://x.com/GrokBotRadar" target="_blank" rel="noreferrer">Fan Grok Bot Radar @GrokBotRadar</a></p></blockquote><p><img src="'+B+'" alt="How to Stop Your Grok Bot From Eating a Week of Usage in a Day" loading="lazy" decoding="async"></p><p><img src="'+_+'" alt="How to Stop Your Grok Bot From Eating a Week of Usage in a Day" loading="lazy" decoding="async"> Fan Grok Bot Radar（@GrokBotRadar）拆解发现，<strong>用量本质是唤醒频次乘以单次重读完整历史上下文</strong>，每次触发都会连带重读完整对话记录。作者给出了五条降耗实操：</p><ol><li>压缩频次：全天 15 分钟轮询缩减为工作时段定时检查。</li><li>切断历史：<strong>定期用 Duplicate 复制 Bot 重置历史</strong>（自述单次 Token 降低约 75%，未核）。</li><li>物理拆分：高频聊天的 Bot 和跑例程的 Bot 分开部署。</li><li>脚本兜底：邮件筛选等确定性杂务交给云电脑终端跑 Python 脚本。</li><li>验收标准：<strong>给监控例程加上静默规则</strong>，无异常绝不产生无用消息。</li></ol><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/HO20w5OQQiNtNuk92mhcdQEynOi" target="_blank" rel="noreferrer">阅读原文</a></p><h3 id="grok-bot-memory-engineering-how-one-agent-learns-with-a-team-rari" tabindex="-1">Grok Bot Memory Engineering: How One Agent Learns With a Team｜rari <a class="header-anchor" href="#grok-bot-memory-engineering-how-one-agent-learns-with-a-team-rari" aria-label="Permalink to &quot;Grok Bot Memory Engineering: How One Agent Learns With a Team｜rari&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/0xwhrrari/status/2107093781807775896" target="_blank" rel="noreferrer">Grok Bot Memory Engineering: How One Agent Learns With a Team</a><br> 作者：<a href="https://x.com/0xwhrrari" target="_blank" rel="noreferrer">rari @0xwhrrari</a></p></blockquote><p><img src="'+w+'" alt="Grok Bot Memory Engineering: How One Agent Learns With a Team" loading="lazy" decoding="async"></p><p><img src="'+G+'" alt="Grok Bot Memory Engineering: How One Agent Learns With a Team" loading="lazy" decoding="async"> rari（@0xwhrrari）这套架构专门解决多人共享 Bot 时的记忆污染问题，适合工程架构师。他把上下文拆成五类容器，分别存放实时源、技能和团队记忆，以及个人笔记与任务状态。</p><ul><li><strong>快慢时钟分流</strong>：语气等慢时钟信息存入团队记忆；价格与库存等快时钟数据必须每次实时查询源系统。</li><li>审查卡片：标清责任人、出处与失效日期，经核准后才允许写入共享池。</li><li>验收防线：<strong>正式上线前测试跨用户隐私泄露与频道权限边界</strong>，把错误记忆当成数据事故严肃排查和回滚。</li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/FW0Ww6c4nivdMgkK7YncWmBent0" target="_blank" rel="noreferrer">阅读原文</a></p>',91)])])}const S=g(q,[["render",A]]);export{E as __pageData,S as default};
